INSERT INTO "habilidade_ef" VALUES('EF07CI15','bncc-2018','Interpretar fenômenos naturais (como vulcões, terremotos e tsunamis) e justificar a rara ocorrência desses fenômenos no Brasil, com base no modelo das placas tectônicas.','ef-comp-ci','unidade_tematica','ef-comp-ci-ut-terra-e-universo',NULL,NULL,'vigente','dados-2026.07',NULL,'bncc-2018','BNCC_Ensino Fundamental.xlsx','exportada de downloadbncc.mec.gov.br em 23/06/2023','aba Ciências, linha 80','Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 349');
INSERT INTO "habilidade_ef" VALUES('EF07CI16','bncc-2018','Justificar o formato das costas brasileira e africana com base na teoria da deriva dos continentes.','ef-comp-ci','unidade_tematica','ef-comp-ci-ut-terra-e-universo',NULL,NULL,'vigente','dados-2026.07',NULL,'bncc-2018','BNCC_Ensino Fundamental.xlsx','exportada de downloadbncc.mec.gov.br em 23/06/2023','aba Ciências, linha 81','Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 349');
INSERT INTO "habilidade_ef" VALUES('EF08CI01','bncc-2018','Identificar e classificar diferentes fontes (renováveis e não renováveis) e tipos de energia utilizados em residências, comunidades ou cidades.','ef-comp-ci','unidade_tematica','ef-comp-ci-ut-materia-e-energia',NULL,NULL,'vigente','dados-2026.07',NULL,'bncc-2018','BNCC_Ensino Fundamental.xlsx','exportada de downloadbncc.mec.gov.br em 23/06/2023','aba Ciências, linha 82','Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 351');
INSERT INTO "habilidade_ef" VALUES('EF08CI02','bncc-2018','Construir circuitos elétricos com pilha/bateria, fios e lâmpada ou outros dispositivos e compará-los a circuitos elétricos residenciais.','ef-comp-ci','unidade_tematica','ef-comp-ci-ut-materia-e-energia',NULL,NULL,'vigente','dados-2026.07',NULL,'bncc-2018','BNCC_Ensino Fundamental.xlsx','exportada de downloadbncc.mec.gov.br em 23/06/2023','aba Ciências, linha 83','Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 351');
