INSERT INTO "habilidade_em" VALUES('EM13LGG101','bncc-2018','Compreender e analisar processos de produção e circulação de discursos, nas diferentes linguagens, para fazer escolhas fundamentadas em função de interesses pessoais e coletivos.','em-area-lgg',NULL,'vigente','dados-2026.07',NULL,'bncc-2018','BNCC_Ensino_Medio.xlsx','exportada de downloadbncc.mec.gov.br em 23/06/2023','aba ''Hab. de Linguagens e suas Tecn'', linha 4','Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 493');
