INSERT INTO "marco_legal" VALUES('constituicao-1988','constituicao','Constituição da República Federativa do Brasil de 1988','Carta constitucional em vigor. Os arts. 205 a 214 estabelecem a educação como direito de todos e dever do Estado e da família, fixam os princípios do ensino e preveem o plano nacional de educação.','https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm',NULL);
INSERT INTO "marco_legal" VALUES('lei-8069-1990','lei','Lei nº 8.069, de 13 de julho de 1990','Dispõe sobre o Estatuto da Criança e do Adolescente e dá outras providências.','https://www.planalto.gov.br/ccivil_03/leis/l8069.htm',NULL);
INSERT INTO "marco_legal" VALUES('lei-9394-1996','lei','Lei nº 9.394, de 20 de dezembro de 1996','Estabelece as diretrizes e bases da educação nacional (LDB). O art. 26 determina que os currículos da educação básica tenham base nacional comum.','https://www.planalto.gov.br/ccivil_03/leis/l9394.htm',NULL);
INSERT INTO "marco_legal" VALUES('emenda-constitucional-59-2009','emenda_constitucional','Emenda Constitucional nº 59, de 11 de novembro de 2009','Torna a educação básica obrigatória e gratuita dos 4 aos 17 anos de idade, amplia os programas suplementares a todas as etapas e insere a universalização entre as diretrizes do plano nacional de educação (altera os arts. 208, 211 e 214 da Constituição).','https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc59.htm',NULL);
INSERT INTO "marco_legal" VALUES('resolucao-cne-ceb-5-2009','resolucao','Resolução CNE/CEB nº 5, de 17 de dezembro de 2009','Fixa as Diretrizes Curriculares Nacionais para a Educação Infantil.','https://www.gov.br/mec/pt-br/cne/pdf/resolucoes-do-cne/ceb/2009/rceb005_09.pdf',NULL);
INSERT INTO "marco_legal" VALUES('resolucao-cne-ceb-4-2010','resolucao','Resolução CNE/CEB nº 4, de 13 de julho de 2010','Define Diretrizes Curriculares Nacionais Gerais para a Educação Básica.','https://www.gov.br/mec/pt-br/cne/pdf/resolucoes-do-cne/ceb/2010/rceb004_10.pdf',NULL);
INSERT INTO "marco_legal" VALUES('resolucao-cne-ceb-7-2010','resolucao','Resolução CNE/CEB nº 7, de 14 de dezembro de 2010','Fixa Diretrizes Curriculares Nacionais para o Ensino Fundamental de 9 (nove) anos.','https://www.gov.br/mec/pt-br/cne/pdf/resolucoes-do-cne/ceb/2010/rceb007_10.pdf',NULL);
INSERT INTO "marco_legal" VALUES('lei-12796-2013','lei','Lei nº 12.796, de 4 de abril de 2013','Altera a Lei nº 9.394/1996 (LDB) para dispor sobre a formação dos profissionais da educação e dar outras providências; incorpora à LDB a obrigatoriedade da educação básica dos 4 aos 17 anos, incluindo a pré-escola.','https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/lei/l12796.htm',NULL);
INSERT INTO "marco_legal" VALUES('lei-13005-2014','lei','Lei nº 13.005, de 25 de junho de 2014','Aprova o Plano Nacional de Educação (PNE) e dá outras providências. As metas 2, 3 e 7 e suas estratégias preveem a base nacional comum curricular.','https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l13005.htm',NULL);
INSERT INTO "marco_legal" VALUES('lei-13146-2015','lei','Lei nº 13.146, de 6 de julho de 2015','Institui a Lei Brasileira de Inclusão da Pessoa com Deficiência (Estatuto da Pessoa com Deficiência); assegura sistema educacional inclusivo em todos os níveis e adaptações razoáveis, base legal do plano educacional individualizado (PEI).','https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm',NULL);
INSERT INTO "marco_legal" VALUES('lei-13415-2017','lei','Lei nº 13.415, de 16 de fevereiro de 2017','Altera a LDB para reformar o Ensino Médio (formação geral básica e itinerários formativos) e institui a Política de Fomento à Implementação de Escolas de Ensino Médio em Tempo Integral; torna obrigatórios os estudos e práticas de Língua Portuguesa e Matemática nos três anos do Ensino Médio.','https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13415.htm',NULL);
INSERT INTO "marco_legal" VALUES('parecer-cne-cp-15-2017','parecer','Parecer CNE/CP nº 15/2017, aprovado em 15 de dezembro de 2017','Analisa e aprova a Base Nacional Comum Curricular da Educação Infantil e do Ensino Fundamental; fundamentou a Resolução CNE/CP nº 2/2017. Homologado pela Portaria MEC nº 1.570/2017.','https://www.gov.br/mec/pt-br/cne/pdf/pareceres-do-cne/cp/2017/pcp015_17.pdf',NULL);
INSERT INTO "marco_legal" VALUES('resolucao-cne-cp-2-2017','resolucao','Resolução CNE/CP nº 2, de 22 de dezembro de 2017','Institui e orienta a implantação da Base Nacional Comum Curricular, a ser respeitada obrigatoriamente ao longo das etapas e respectivas modalidades no âmbito da Educação Básica.','https://www.gov.br/mec/pt-br/cne/pdf/resolucoes-do-cne/cp/2017/rcp002_17.pdf',NULL);
INSERT INTO "marco_legal" VALUES('resolucao-cne-ceb-3-2018','resolucao','Resolução CNE/CEB nº 3, de 21 de novembro de 2018','Atualiza as Diretrizes Curriculares Nacionais para o Ensino Médio.','https://www.gov.br/mec/pt-br/cne/pdf/resolucoes-do-cne/ceb/2018/rceb003_18.pdf',NULL);
INSERT INTO "marco_legal" VALUES('parecer-cne-cp-15-2018','parecer','Parecer CNE/CP nº 15/2018, aprovado em 4 de dezembro de 2018','Trata da instituição da Base Nacional Comum Curricular do Ensino Médio (BNCC-EM) e da orientação aos sistemas de ensino para sua implementação; fundamentou a Resolução CNE/CP nº 4/2018. Homologado pela Portaria MEC nº 1.348/2018.','https://www.gov.br/mec/pt-br/cne/pdf/pareceres-do-cne/cp/2018/pcp015_18.pdf',NULL);
INSERT INTO "marco_legal" VALUES('resolucao-cne-cp-4-2018','resolucao','Resolução CNE/CP nº 4, de 17 de dezembro de 2018','Institui a Base Nacional Comum Curricular na Etapa do Ensino Médio (BNCC-EM), como etapa final da Educação Básica.','https://www.gov.br/mec/pt-br/cne/pdf/resolucoes-do-cne/cp/2018/rcp004_18.pdf',NULL);
INSERT INTO "marco_legal" VALUES('resolucao-cne-ceb-1-2021','resolucao','Resolução CNE/CEB nº 1, de 28 de maio de 2021','Institui Diretrizes Operacionais para a Educação de Jovens e Adultos nos aspectos relativos ao seu alinhamento à Política Nacional de Alfabetização (PNA) e à Base Nacional Comum Curricular (BNCC), e Educação de Jovens e Adultos a Distância.','https://www.gov.br/mec/pt-br/cne/pdf/resolucoes-do-cne/ceb/2021/rceb001_21.pdf',NULL);
INSERT INTO "marco_legal" VALUES('parecer-cne-ceb-2-2022','parecer','Parecer CNE/CEB nº 2/2022, aprovado em 17 de fevereiro de 2022','Aprova as Normas sobre Computação na Educação Básica, complemento à Base Nacional Comum Curricular (BNCC). Homologado por despacho ministerial publicado no D.O.U. de 3/10/2022.','https://www.gov.br/mec/pt-br/cne/pdf/pareceres-do-cne/ceb/2022/pceb002_22.pdf','O anexo do parecer (objetivos e habilidades de Computação) é o documento-fonte do futuro módulo de Computação: https://www.gov.br/mec/pt-br/cne/pdf/pareceres-do-cne/ceb/2022/anexo-ao-parecer-cneceb-no-2-2022-bncc-computacao.pdf');
INSERT INTO "marco_legal" VALUES('resolucao-cne-ceb-1-2022','resolucao','Resolução CNE/CEB nº 1, de 4 de outubro de 2022','Institui as Normas sobre Computação na Educação Básica, complemento à BNCC, na forma do anexo ao Parecer CNE/CEB nº 2/2022.','https://www.gov.br/mec/pt-br/cne/pdf/resolucoes-do-cne/ceb/2022/rceb001_22.pdf',NULL);
INSERT INTO "marco_legal" VALUES('lei-14945-2024','lei','Lei nº 14.945, de 31 de julho de 2024','Altera a LDB para instituir a Política Nacional de Ensino Médio, redefinindo a carga horária da formação geral básica e a organização dos itinerários formativos do Ensino Médio.','https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14945.htm',NULL);
